import{_ as r,C as t,o,c as s,E as a,a2 as l}from"./chunks/framework.DyLyN3RJ.js";const y=JSON.parse('{"title":"Completion, legality and safety: why three metrics cannot stand in for one another","description":"","frontmatter":{"title":"Completion, legality and safety: why three metrics cannot stand in for one another","date":"2026-11-04","column":"industry-architecture","category":"daily","article_type":"technical-analysis","edition":"research-center","research_question":"多智能体的目标达成、交付验收、轨迹合法性与安全性，在哪些条件下会给出不同判断？","research_question_en":"Under which conditions do multi-agent goal attainment, delivery acceptance, trajectory legality and safety give different judgments?","summary":"Pinned evaluation modules allow full goal progress with failed acceptance, and a legal plan with a safety violation. Synthetic inputs expose predicate scope, not full-system performance.","sources":"Two versioned papers, pinned public metric implementations and same-date internal module experiments","pageClass":"runtime-v6-article","item_id":"SIG-20261104-005","lifecycle":"Published","cover":"/assets/covers/daily-2026-11-04-sig-20261104-005-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"en/industry/2026-11-04-sig-20261104-005.md","filePath":"en/industry/2026-11-04-sig-20261104-005.md","lastUpdated":1793804226000}'),c={name:"en/industry/2026-11-04-sig-20261104-005.md"};function d(p,e,h,u,g,m){const n=t("ArticleCover"),i=t("ArticleTableScroll");return o(),s("div",null,[a(n,{image:"/assets/covers/daily-2026-11-04-sig-20261104-005-cover.png",kicker:"Research",title:"Completion, legality and safety: why three metrics cannot stand in for one another",summary:"Pinned evaluation modules allow full goal progress with failed acceptance, and a legal plan with a safety violation. Synthetic inputs expose predicate scope, not full-system performance.",version:"2026-11-04",languageHref:"/zh/industry/2026-11-04-sig-20261104-005",languageLabel:"中文"}),a(i,{language:"en"}),e[0]||(e[0]=l('<h1 id="completion-legality-and-safety-why-three-metrics-cannot-stand-in-for-one-another" tabindex="-1">Completion, legality and safety: why three metrics cannot stand in for one another <a class="header-anchor" href="#completion-legality-and-safety-why-three-metrics-cannot-stand-in-for-one-another" aria-label="Permalink to &quot;Completion, legality and safety: why three metrics cannot stand in for one another&quot;">​</a></h1><p>A task can score 1 on goal attainment and still fail acceptance. That need not be a statistical mistake: completing requested goals and preserving existing content can be separate checks. In another evaluation module, a true legal-plan flag can coexist with a safety violation.</p><p>These differences appeared in internal experiments that supplied synthetic reports to pinned public metric modules. For engineers interpreting multi-agent evaluations, the useful question is what a field actually checks—and which questions it leaves unanswered. Our bounded judgment is that goal completion, acceptance, trajectory legality and safety diagnostics need separate scopes; one field cannot endorse the others.</p><p>Three evidence roles matter here. Paper experiments remain author-reported. Public code establishes the computation at a particular revision. Our executed module outputs are internal experimental evidence; no independent actor has reproduced these claims. The tables below contain synthetic-input module outputs, not model success rates or production failure estimates.</p><h2 id="full-goal-progress-can-still-fail-acceptance" tabindex="-1">Full goal progress can still fail acceptance <a class="header-anchor" href="#full-goal-progress-can-still-fail-acceptance" aria-label="Permalink to &quot;Full goal progress can still fail acceptance&quot;">​</a></h2><p>The MAC-Bench paper distinguishes goal-group progress from resolved rate. Resolution additionally requires applicable preservation conditions; a normal episode ending is also separate from resolution. <a href="https://arxiv.org/html/2611.01728v1" target="_blank" rel="noreferrer">Section 4.1 and Appendix G.2</a> define the authors&#39; metrics, rather than a universal acceptance standard for business tasks.</p><p>The same-date research executed paired inputs against the pinned <a href="https://raw.githubusercontent.com/rzchen777-wq/MAC_Bench/1024991685762c54977ac45e1df4b6f6641a3e1b/src/mac_bench/evaluation/reports/metrics.py" target="_blank" rel="noreferrer">metric implementation</a>, producing these internal results.</p><table tabindex="0"><thead><tr><th>Synthetic input</th><th style="text-align:right;">Goal completion</th><th style="text-align:right;">Progress score</th><th>Task success</th><th style="text-align:right;">Resolved-rate contribution</th></tr></thead><tbody><tr><td>Accepted, all goals complete</td><td style="text-align:right;">1</td><td style="text-align:right;">1</td><td>true</td><td style="text-align:right;">1</td></tr><tr><td>Rejected, all goals complete</td><td style="text-align:right;">1</td><td style="text-align:right;">1</td><td>false</td><td style="text-align:right;">0</td></tr><tr><td>Evaluation error, input still carries goal value 1</td><td style="text-align:right;">null</td><td style="text-align:right;">null</td><td>null</td><td style="text-align:right;">null</td></tr></tbody></table><p>Source: same-date internal accepted, full-progress/rejected and unavailable-evaluation controls; every input is synthetic.</p><p>The decisive boundary is at the input. The experiment supplies an acceptance verdict; it does not run a real task grader. It shows that the adapter permits full goal progress alongside failure, rather than discovering a naturally occurring task exploit.</p><p>The paper separately reports a task-level example: five goals remain complete after a template-handling mutation corrupts retained error metadata, causing preservation failure. That corruption-and-repair case remains the authors&#39; evidence in <a href="https://arxiv.org/html/2611.01728v1" target="_blank" rel="noreferrer">Section 4.4 and Appendices D.3–D.4</a>; we did not independently execute its grader. It motivates the preservation requirement, while the internal module control shows how the distinction survives in result fields. Together they still do not constitute an end-to-end reproduction.</p><h2 id="a-legal-plan-label-can-exceed-its-checked-scope" tabindex="-1">A legal-plan label can exceed its checked scope <a class="header-anchor" href="#a-legal-plan-label-can-exceed-its-checked-scope" aria-label="Permalink to &quot;A legal-plan label can exceed its checked scope&quot;">​</a></h2><p>The pinned <a href="https://raw.githubusercontent.com/AgibotGeneral/CoCoBench/baa4dd5d9669251089c8d72ba7bb0532323b06a4/benchmark/eval/metrics.py" target="_blank" rel="noreferrer">CoCoBench metric code</a> computes final success, action legality, coordination-construct scores and safety violations separately. Its legal-plan flag primarily checks undeclared skills and precondition violations. It does not fold all safety diagnostics into a single Boolean.</p><p>An internal control declares two agents, authorizes one to use BreakObject, and declares its target fragile. The supplied report retains final success and gives each agent one action. The module returns a true legal-plan flag, a D1 load-allocation score of 1, and one safety violation. The allocation score describes action distribution; it is not a safety score.</p><p>Paired controls sharpen that scope. An undeclared skill makes legal-plan false. A failed interaction classified as “already clean” does not increment dependency violations, while a non-exempt failed pickup does. The latter is an output of a report classifier, rather than confirmation of the physical cause of failure in a scene.</p><p>This coexistence is not a defect verdict against the upstream implementation. Final success is supplied by the fixture, not produced by the simulator or a task grader. We have not established that every synthetic combination is naturally reachable. The narrower conclusion is that readers cannot expand “legal plan” into comprehensive safety or authorization certification, or interpret high load allocation as overall task quality.</p><h2 id="missingness-and-low-signal-belong-beside-the-mean" tabindex="-1">Missingness and low signal belong beside the mean <a class="header-anchor" href="#missingness-and-low-signal-belong-beside-the-mean" aria-label="Permalink to &quot;Missingness and low signal belong beside the mean&quot;">​</a></h2><p>The same internal controls examine construct engagement thresholds.</p><table tabindex="0"><thead><tr><th>Synthetic trajectory</th><th>Legal plan</th><th style="text-align:right;">Construct score</th><th>Sample state</th></tr></thead><tbody><tr><td>Zero actions</td><td>null</td><td style="text-align:right;">null</td><td>No actions</td></tr><tr><td>One action</td><td>true</td><td style="text-align:right;">null</td><td>Low signal</td></tr><tr><td>One action from each of two agents</td><td>true</td><td style="text-align:right;">1</td><td>Two engagement events, scored</td></tr></tbody></table><p>Source: same-date internal zero-action, one-action and balanced two-agent controls.</p><p>Zero actions supply neither a legality counterexample nor evidence of passing legality. One action does not support this construct score either. The engagement rules in the <a href="https://arxiv.org/html/2608.28266v1" target="_blank" rel="noreferrer">construct and scoring definitions</a> therefore need to accompany the score.</p><p>The acceptance denominator needs similar visibility. For one accepted, one rejected and one unavailable evaluation, the internal experiment reports two scored episodes, resolved rate 0.5 and mean progress 1, plus one explicitly excluded unavailable evaluation. That 0.5 is not an overall delivery probability across all three attempts. Exclusion is not inherently wrong; concealing the excluded population misleads readers about the denominator.</p><p>Our engineering interpretation is to retain goal attainment, acceptance, measured trajectory constraints and evidence coverage together. A short label needs its actual predicate, applicable population and missingness rule to support a decision. The two benchmarks differ in environment, tasks and denominators. Their comparison cannot yield a pooled success rate or a universal ranking of multi-agent architectures.</p><h2 id="evidence-and-sources" tabindex="-1">Evidence and sources <a class="header-anchor" href="#evidence-and-sources" aria-label="Permalink to &quot;Evidence and sources&quot;">​</a></h2><p>This article consumes completed same-date research and internal experiments; no new experiments were performed during writing. The pinned MAC-Bench revision is <code>1024991685762c54977ac45e1df4b6f6641a3e1b</code>, and the CoCoBench revision is <code>baa4dd5d9669251089c8d72ba7bb0532323b06a4</code>. Five MAC controls and seven CoCo controls passed. Public module paths are linked above; the <a href="/joinwell52/assets/evidence/2026-11-04-sig-20261104-005/sig-20261104-005-evidence.json">internal inputs, expectations and actual outputs</a> are retained with the candidate materials.</p><p>The <a href="https://arxiv.org/html/2611.01728v1" target="_blank" rel="noreferrer">MAC-Bench paper</a> supplies author-reported goal, acceptance and preservation evidence. The <a href="https://arxiv.org/html/2608.28266v1" target="_blank" rel="noreferrer">CoCoBench paper</a> supplies the authors&#39; construct, legality and success definitions. Their current public code is a locatable implementation fact, rather than third-party evidence examining the same performance claim.</p><p>Publication is not validation; citation is not endorsement; peer review is not proof. Self-reported evidence is not independent evidence, and successful module execution does not establish general validity.</p><h2 id="which-combinations-arise-during-real-execution-remains-open" tabindex="-1">Which combinations arise during real execution remains open <a class="header-anchor" href="#which-combinations-arise-during-real-execution-remains-open" aria-label="Permalink to &quot;Which combinations arise during real execution remains open&quot;">​</a></h2><p>We did not download and execute complete task packages, original run archives or private graders, and did not run the embodied simulator. The current public commits have not been established as line-for-line equivalents of the original experimental revisions. These results cannot measure natural occurrence frequencies, reproduce paper success rates or provide safety certification.</p><p>The next research question is which report combinations actually arise from execution trajectories at fixed task and code versions, and how separate diagnostics change real acceptance decisions. Until that evidence exists, engineers can preserve and explain each check&#39;s scope. A comprehensive-sounding metric name cannot substitute for an unperformed check.</p>',30))])}const b=r(c,[["render",d]]);export{y as __pageData,b as default};
